const TTL_MS = 60_000;
const MAX_ENTRIES = 10_000;
const cache = new Map<string, { at: number; p: Promise<Profile> }>();

export function getProfileCached(id: string): Promise<Profile> {
  const hit = cache.get(id);
  if (hit && Date.now() - hit.at < TTL_MS) return hit.p;

  // Cache the promise, not the value: concurrent misses share one fetch.
  const p = fetchProfile(id);
  p.catch(() => {
    if (cache.get(id)?.p === p) cache.delete(id); // don't cache failures
  });
  cache.delete(id); // re-insert at end so eviction order is by age
  cache.set(id, { at: Date.now(), p });
  if (cache.size > MAX_ENTRIES) cache.delete(cache.keys().next().value!);
  return p;
}

// Call from every profile write path (update, delete, avatar change).
export const invalidateProfile = (id: string) => cache.delete(id);
